import {canyonPointAt,projectCanyon} from '../../dist/canyon-track.js';
const wrap=a=>Math.atan2(Math.sin(a),Math.cos(a)),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),smooth=(a,b,v)=>{const t=clamp((v-a)/(b-a),0,1);return t*t*(3-2*t);};
export function canyonDriverInput(s,{speed=14,gain=2,look=.5,offsetGain=.035}={}){const p=projectCanyon(s.x,s.z),v=s.linearSpeed,lead=canyonPointAt(p.progress+v*look),curvature=wrap(canyonPointAt(lead.progress+1).heading-canyonPointAt(lead.progress-1).heading)/2;const intent=clamp(-v*curvature*(1+(v/45)**2)/.9366,-1,1);let low=0,high=1;for(let i=0;i<12;i++){const m=(low+high)/2;if(m*(.55+.45*m)<Math.abs(intent))low=m;else high=m;}const steer0=Math.sign(intent)*(.08+.92*(low+high)/2),beta=-Math.sign(steer0)*.62*smooth(6,13,v)*smooth(.15,.65,Math.abs(steer0));const error=wrap(lead.heading+beta+Math.atan(p.offset*offsetGain)-s.heading);return {steering:clamp(steer0-error*gain,-1,1),speedDemand:speed/42};}
